css:
/* Teravera: restrained surfaces with cobalt accents. */
:root:not(.dark) { --tv-canvas: #fafbfd; --tv-panel: #fff; --tv-side: #eef1f6; --tv-border: #dfe4ed; --tv-link: #0236ad; --tv-ink: #24314a; --tv-muted: #66738a; --tv-shadow: rgba(20,40,80,.045); }
:root.dark { --tv-canvas: #0b1426; --tv-panel: #111e36; --tv-side: #0c1525; --tv-border: #253249; --tv-link: #9bbbfa; --tv-ink: #dce5f4; --tv-muted: #94a4be; --tv-shadow: rgba(0,0,0,.16); }
[data-slot="sidebar-inner"]::before { content: none !important; display: none !important; }
[data-slot="sidebar"], [data-slot="sidebar-inner"] { background: var(--tv-side) !important; color: var(--tv-ink) !important; --foreground: var(--tv-ink); --muted-foreground: var(--tv-muted); }
[data-slot="sidebar"] [data-thread-item] { border-radius: 7px !important; }
[data-slot="sidebar"] svg.lucide { stroke-width: 1.6; }
[data-chat-header] { background: var(--tv-panel) !important; border-bottom: 1px solid var(--tv-border) !important; }
[data-chat-header]::after { content: "TERAVERA"; display: block; flex-shrink: 0; margin-left: auto; padding: 0 16px; color: var(--tv-link); font-size: 10px; font-weight: 650; letter-spacing: .16em; opacity: .65; pointer-events: none; }
[data-workspace-area="conversation"] { background: var(--tv-canvas) !important; }
[data-slot="composer-host"] { background: var(--tv-panel) !important; border: 1px solid var(--tv-border) !important; border-radius: 12px !important; box-shadow: 0 3px 14px var(--tv-shadow) !important; }
[data-user-message-bubble] { border-radius: 12px !important; }
[data-thread-details-card], [data-slot="settings-group"] { border: 1px solid var(--tv-border) !important; border-radius: 10px !important; box-shadow: none !important; }
.chat-markdown a { color: var(--tv-link); text-underline-offset: 3px; }
@media (max-width: 800px) { [data-chat-header]::after { display: none; } }

/* Visible brand identity, without an extra sidebar header row. */
:root:not(.dark) { --tv-side: #e8eefc; --tv-ink: #17366c; --tv-muted: #526d99; --tv-brand: #0236ad; --tv-logo: url("data:image/svg+xml;base64,"); }
:root.dark { --tv-side: #0b2045; --tv-ink: #e7efff; --tv-muted: #a6bee5; --tv-brand: #8cb4ff; --tv-logo: url("data:image/svg+xml;base64,"); }
[data-chat-header] { border-top: 2px solid var(--tv-brand) !important; }
[data-chat-header]::after { content: ""; display: block; width: 112px; height: 28px; flex: 0 0 112px; margin-left: auto; margin-right: 20px; padding: 0; background-image: var(--tv-logo); background-repeat: no-repeat; background-position: center; background-size: contain; opacity: 1; }
[data-slot="sidebar-inner"] { border-right: 1px solid var(--tv-border); }
[data-slot="sidebar"] [data-thread-item][aria-current="page"] { box-shadow: inset 3px 0 0 var(--tv-brand); }
[data-slot="composer-host"]:focus-within { border-color: var(--tv-brand) !important; box-shadow: 0 0 0 2px color-mix(in srgb, var(--tv-brand) 12%, transparent) !important; }
@media (max-width: 800px) { [data-chat-header]::after { width: 84px; flex-basis: 84px; margin-right: 8px; } }
